quests[32650] = { id = 32650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Shado-Pan II", description = "Nun, für heute ist unsere Arbeit getan! Jetzt müsst Ihr nur noch auf die morgige Ernte warten.\n\nSobald Euer Grünkohl erntereif ist, müsst Ihr ihn nur noch für die Abholung einpacken.\n\nFür die Shado-Pan ist nur der beste Kohl gut genug!", sourceObjective = "Erntet 8 reife Grünkohlpflanzen und liefert 40 Stück Grünkohl an die Shado-Pan.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Legt den Grünkohl vorsichtig in die Kiste! Ein Vertreter der Shado-Pan wird in Kürze ankommen, um ihn einzusammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32651] = { id = 32651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Introflug" }
quests[32652] = { id = 32652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Lüfte!", description = "Wir haben einen Weg gefunden, die Waffenproduktion der Mogu aufzuhalten, und es hat etwas mit der Kreatur zu tun, die Ihr von den Zandalari befreit habt.\n\nSprecht mit mir, wenn Ihr bereit seid, mehr zu erfahren.", sourceObjective = "Verschafft Euch Zugang zu den Blitzaderminen.", progress = "Es ist an der Zeit, Eure Mission zu beginnen!", completion = "Unglaubliche Arbeit. Das bietet uns eine monumentale Gelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32653] = { id = 32653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Die Himmlischen Erhabenen I", description = "<Yoons vertraute Handschrift bedeckt das rissige Papier.>\n\nDie Schüler drüben in Chi-Jis Wiege brauchen Streifenmelonen. Anscheinend benutzen sie sie in ihren Übungen.\n\nEin Repräsentant wird bis morgen vorbeikommen und alle Streifenmelonen mitnehmen, die Ihr erübrigen könnt.", sourceObjective = "Pflanzt 8 Streifenmelonensamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[32654] = { id = 32654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mauer muss weg!", description = "Die Zeit ist gekommen. Unsere Stellung ist gut genug befestigt, sodass wir es riskieren können, in die Behausung des Donnerkönigs vorzudringen. Leider sieht es nicht so aus, als ob er dieses Tor in nächster Zeit öffnen wird.\n\nIch vermute also, dass wir uns unser eigenes Tor schaffen müssen. Lasst es mich wissen, wenn Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer und dringt dann in die untere Stadt vor, um sie für die Allianz zu erobern.", completion = "Mit Eurer Hilfe sind wir unserem Ziel einen riesigen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32655] = { id = 32655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine waghalsige Idee", description = "Kriegsschiffe der Zandalari plündern die Meere um diese Insel herum. Sie bringen Soldaten und Kriegsbestien aus Zandalar, um Lei Shens Armeen aufzustocken.\n\nWenn wir die Werft des Palastes in unseren Besitz bringen können, ist die Versorgungsroute des Donnerkönigs abgeschnitten, und Euer Standort hier ist gesichert.\n\nIch habe einen Plan, um genau das zu bewerkstelligen, und wir werden keine ganze Armee dazu brauchen.", sourceObjective = "Infiltriert den Sturmgepeitschten Hafen und öffnet das Tor zum Hof von innen. Sprecht mit Taoshi, um die Mission zu beginnen.", completion = "Gut gemacht. Dieses Kriegsschiff wird nicht so bald wieder Feuer auf uns niedergehen lassen.\n\nTaran Zhu hat mir mitgeteilt, dass die Shado-Pan den Sturmgepeitschten Hafen bewachen werden, sodass wir die Ressourcen der Kirin Tor verwenden können, um den Angriff andernorts fortzuführen. Taoshi wird dort sein. Ich bin sicher, dass sie gern wieder mit Euch zusammenarbeiten würde.\n\nWir sind für Euren Beitrag dankbar, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[32656] = { id = 32656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz von Shan'Bu", description = "Lei Shen fand zu Beginn seines Feldzuges ein Gelege seltener Sturmdracheneier. Eine dieser Kreaturen - Nalak - war besonders brutal und tötete alle seine Pfleger, also nahm Lei Shen sich seiner an.\n\nNun arbeitet Shan'Bu, einer der treuesten Diener Lei Shens, daran, den Drachen wiederzuerwecken.\n\nEs wird höchste Zeit, gegen Shan'Bu loszuschlagen!\n\nSprecht mich wieder an, sobald Ihr bereit seid, den Angriff zu starten!", sourceObjective = "Besiegt Shan'Bu.", completion = "Ihr habt es geschafft, {class}! Shan'Bu ist ein für alle Mal besiegt und wir haben erfahren, dass Lor'themar möglicherweise nicht der ist, der er zu sein scheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[32657] = { id = 32657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Die Himmlischen Erhabenen II", description = "Sobald Eure Streifenmelonen erntereif sind, müsst Ihr sie nur noch für die Abholung einpacken.\n\nEin Schüler von Chi-Jis Wiege wird in Kürze eintreffen, um die Bestellung abzuholen.", sourceObjective = "Erntet 8 reife Streifenmelonenpflanzen und liefert 40 Streifenmelonen an die Himmlischen Erhabenen.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Werft die Streifenmelonen in die Kiste! Und schon ist die Bestellung der Himmlischen Erhabenen transportfertig!", sourceObjectiveStatus = "unverified-source-field" }
quests[32658] = { id = 32658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Die Klaxxi I", description = "<Auch wenn Yoons Handschrift zu Wünschen übrig lässt, ist es trotzdem schön, ein wenig von ihm auf dem Gehöft zu haben.>\n\nHeute morgen ist eine Bestellung von den Klaxxi eingetroffen. Seltsamerweise bitten sie für irgendwelche Forschungszwecke um Mogukürbisse.\n\nMeiner Erfahrung nach sollte man ihnen nicht allzu viele Fragen stellen...\n\nFangt am besten mit ihrer Bestellung an. Ich würde nur ungern sehen, was ein Insekt von dieser Größe sonst mit Eurer Ernte anstellen könnte!", sourceObjective = "Pflanzt 8 Mogukürbissamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[32659] = { id = 32659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Die Klaxxi II", description = "Sobald Eure Mogukürbisse erntereif sind, müsst Ihr sie nur noch für die Abholung einpacken.\n\nIch an Eurer Stelle würde nicht trödeln. Die Klaxxi sind nicht gerade für ihre Geduld bekannt!", sourceObjective = "Erntet 8 reife Mogukürbispflanzen und liefert 40 Mogukürbisse an die Klaxxi.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Werft die Mogukürbisse in die Kiste! In Kürze wird ein Vertreter der Klaxxi eintreffen, um sie mitzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32661] = { id = 32661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Aalun am Eingang zur Exodar auf der Azurmythosinsel. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Aalun.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Torallius ist gleich dort drüben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32662] = { id = 32662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Ultham am Gehöft Bernruh in Dun Morogh, an der östlichen Straße aus Eisenschmiede heraus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Ultham Eisenhorn.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Veron Bernruh steht direkt vorm Tor des Gehöfts.", sourceObjectiveStatus = "unverified-source-field" }
quests[32663] = { id = 32663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Binjy Federpfiff.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Milli befindet sich gleich dort drüben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32664] = { id = 32664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Jartsam in der Enklave des Cenarius in Darnassus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Jartsam.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Lelanai erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32665] = { id = 32665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Mei Lin nördlich des Zwergenviertels in Sturmwind. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Mei Lin.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier beim alten Weißnase erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32666] = { id = 32666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Warlock - Green Fire" }
quests[32667] = { id = 32667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Sanftpfote im Tal der Ehre in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Sanftpfote.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Schildkrötenmeisterin Odai erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32668] = { id = 32668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Perascamin bei Thurons Aufzucht, südöstlich vom Hirtentor von Silbermond aus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Perascamin.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt draußen bei Winaestra erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32669] = { id = 32669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Kildar im Tal der Ehre in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Kildar.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Ogunaro erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32670] = { id = 32670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Kar Sturmsang im Dorf der Bluthufe in Mulgore. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Kar Sturmsang.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Harb Klauenhuf erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32671] = { id = 32671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Xar'Ti in Sen'jin im südlichen Durotar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Xar'Ti.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Zjolnir erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32672] = { id = 32672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Velma Warnam in Brill in Tirisfal. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Velma Warnam.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Zachariah Post erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32673] = { id = 32673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Levi Ladestock im Tal der Geister in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Levi Ladestock.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Kall Goldkettchen erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32674] = { id = 32674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Fliegen ist leichter", description = "Der Himmel ruft Euch! Es ist Zeit, Fliegen zu lernen!\n\nBesucht Maztha die Fluglehrerin am Himmelspfad in Orgrimmar.\n\nUnd vergesst nicht, ein Flugreittier zu erwerben!", sourceObjective = "Findet Maztha.", completion = "Ah, gut Euch zu sehen. Ihr seht aus, als wärt Ihr bereit, Euch in die Lüfte zu schwingen!\n\nDenkt daran, Ihr könnt ein Flugreittier von Drakma hinter mir kaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32675] = { id = 32675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Fliegen ist leichter", description = "Der Himmel ruft Euch! Es ist Zeit, Fliegen zu lernen!\n\nBesucht die Fluglehrerin Bralla Wolkenflug am Greifenhorst in Sturmwind.\n\nUnd vergesst nicht, ein Flugreittier zu erwerben!", sourceObjective = "Findet Bralla Wolkenflug.", completion = "Ah, gut Euch zu sehen. Ihr seht aus, als wärt Ihr bereit, Euch in die Lüfte zu schwingen!\n\nDenkt daran, Ihr könnt ein Flugreittier von Tannec Steinschnabel da drüben kaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32676] = { id = 32676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgedehnter Landgang", description = "Die Zandalari haben bereits begonnen, dieses Kriegsschiff zu reparieren, aber wir können es mit minimalem Aufwand untauglich halten.\n\nEntfernt einfach den neuen Kapitän von seinem Posten und stehlt die Schadensberichte des Schiffes aus dieser Werkstatt vor dem Gewölbe.\n\nKein Kapitän. Keine Reparaturen. Kein Kriegsschiff.", sourceObjective = "Stehlt die Werkstattsaufträge und tötet den neuen Kapitän des Kriegsschiffes der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32677] = { id = 32677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer plündern", description = "Die Prall Gefüllte Kammer ist ein Hort von Lei Shens bösartigsten Waffen und gepriesensten Schätzen – es dürfte nicht allzu überraschend sein, dass das oft ein und dasselbe ist.\n\nBesonders ein Artefakt, ein Amulett, das als das Halsband der Stürme bekannt ist, könnte uns dabei helfen, seine scheinbare Herrschaft über Blitze zu verstehen.\n\nBrecht in die Kammer ein und tötet den Schatzmeister. Nehmt seinen Schlüssel und bergt das Amulett aus einer Truhe im hinteren Teil der Kammer.", sourceObjective = "Stehlt das Halsband der Stürme aus der Prall Gefüllten Kammer.", progress = "Ihr habt hoffentlich gute Nachrichten.", completion = "Ah, ich erkenne ein mächtiges Artefakt, wenn ich eines sehe. Es war eine weise Entscheidung, es zu mir zu bringen. Ich werde Aethas sogleich anweisen, es zu untersuchen - vielleicht können wir es zu unserem Vorteil nutzen.\n\nIn der Zwischenzeit nehmt dies im Austausch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32678] = { id = 32678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Donner ruft", description = "Die Zeit ist gekommen, den Donnerkönig anzugreifen!\n\nIn der Nähe der Shado-Pan-Garnison in der Tonlongsteppe wartet eine kleine Gruppe Sonnenhäscher auf Euch.\n\nMeldet Euch bei Späherhauptmann Elsia, um weitere Anweisungen zu erhalten.", sourceObjective = "Meldet Euch bei Späherhauptmann Elsia in der Shado-Pan-Garnison in der Tonlongsteppe.", completion = "Wir müssen uns beeilen, {name}! Die anderen sind vorgegangen, aber ich werde Euch alles auf dem Flug erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32679] = { id = 32679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Donner ruft", description = "Die Zeit ist gekommen, den Donnerkönig anzugreifen!\n\nIn der Nähe der Shado-Pan-Garnison in der Tonlongsteppe wartet eine kleine Gruppe Kirin Tor auf Euch.\n\nMeldet Euch bei Vereesa Windläufer, um weitere Anweisungen zu erhalten.", sourceObjective = "Meldet Euch bei Vereesa Windläufer in der Shado-Pan-Garnison in der Tonlongsteppe.", completion = "Wir müssen uns beeilen, {name}! Die anderen sind vorgegangen, aber ich werde Euch alles auf dem Flug erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32680] = { id = 32680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturm braut sich zusammen", description = "Wir haben keine Zeit zu verlieren, {name}. Jeder Moment, den wir hier vertrödeln, gibt Jaina und den Kirin Tor weitere Teile der Insel preis.\n\nLor'themar wartet auf uns. Sprecht mit mir, wenn Ihr bereit seid, abzureisen. Ich werde Euch selbst hinbringen.", sourceObjective = "Reist mit Späherhauptmann Elsia zur Insel des Donners.", progress = "Diese Insel birgt viele Geheimnisse.", completion = "Ihr seid gerade rechtzeitig gekommen, {race}. Es ist von äußerster Wichtigkeit, dass wir diese Küste vor den Kirin Tor einnehmen.\n\nEs gibt viel zu erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[32681] = { id = 32681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturm braut sich zusammen", description = "Wir haben keine Zeit zu verlieren, {name}. Jeder Moment, den wir hier vertrödeln, gibt den Sonnenhäschern weitere Teile der Insel preis.\n\nLady Jaina Prachtmeer wartet auf uns. Wir sollten sie nicht noch länger warten lassen. Sprecht mit mir, wenn Ihr bereit seid, abzureisen. Ich werde Euch selbst hinbringen.", sourceObjective = "Reist mit Vereesa Windläufer zur Insel des Donners.", progress = "Hier liegt der Schlüssel zu unserer Sicherheit, {name}. Ich kann bis ins Mark meiner Knochen spüren, dass wir hierher gehören.", completion = "Ihr kommt gerade rechtzeitig, {name}. Dieses Land muss von den Kirin Tor kontrolliert werden, zum Wohl aller. Das wird keine leichte Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32682] = { id = 32682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gute Erde", description = "Wie Ihr wisst, {name}, werde ich nicht jünger. Man kann nicht für immer ein drahtiger junger Pandaren bleiben, wisst Ihr.\n\nIch suche jemanden, der meine Pflichten hier im Bund der Ackerbauern übernimmt, und niemand wäre geeigneter als Bauer Yoon.\n\nEr hat noch viel zu lernen, aber er hat einen brauchbaren Kopf auf den Schultern und, was wichtiger ist, ein großzügiges Herz.\n\nGlaubt Ihr, er könnte Interesse haben?", sourceObjective = "Sprecht mit Bauer Yoon.", completion = "Ich wusste doch, dass Ihr ihn überzeugen würdet, {name}. Ihr habt mein Herz beruhigt, nun da ich weiß, dass die Ackerbauern in guten Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[32683] = { id = 32683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt also Schmied werden…", description = "Es ist zwar am besten, die Eigenschaften der einfachen Metalle zu erlernen und Euch hochzuarbeiten, aber es ist möglich zu lernen, wie man ein guter Schmied wird, indem man die verschiedenen Anwendungen von Geistereisen für den alltäglichen Gebrauch erlernt. Wenn Ihr diesen Pfad wählen wollt, um ein Zenmeister der Schmiedekunst zu werden, kann ich Euch die ersten Schritte zeigen. Welchen Pfad Ihr auch wählt, Ihr könnt Euch meinen Respekt verdienen, indem Ihr mir beweist, dass Ihr einen geisterhaften Dietrich herstellen könnt.", sourceObjective = "Erschafft einen geisterhaften Dietrich, indem Ihr 500 Fertigkeitspunkte in Schmiedekunst erlangt. Falls Ihr Euch mithilfe von Pandarenmaterialien in der Schmiedekunst üben wollt, könnt Ihr von Cullen Hammerstirn ein Eurer Fertigkeitsstufe angemessenes Ausbildungsprojekt erhalten.", progress = "Wie machen sich Eure Studien?", completion = "Gut gemacht. Ihr seid bereit, ein Zenmeister der Schmiedekunst zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32684] = { id = 32684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt Fisch?", description = "Ihr sucht einen Goldkarpfen? Oder einen anderen pandarischen Fisch? Ich bin ja selbst kein Angler, aber da ist einer am Fluss, der den Durchreisenden hier das Angeln beigebracht hat. Wenn Ihr geht und mit ihm sprecht, gibt er Euch sicher ein paar Fische und bringt es Euch auch bei.", sourceObjective = "Sprecht mit Ben mit der dröhnenden Stimme.", completion = "Ah! Möchtet Ihr das Angeln erlernen? Da seid Ihr bei mir ganz richtig. Doch zuerst - ein paar Fische für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[32685] = { id = 32685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Angelrute erforderlich!", description = "Ihr braucht in Pandaria nicht einmal eine Angelrute in die Hand zu nehmen!\n\nDie Gewässer WIMMELN von Fischen. Ihr fangt eigentlich fast jedes Mal einen, solange Ihr auch aufpasst. Versucht es einmal!", sourceObjective = "Fangt fünf Goldkarpfen. Versucht es ohne Angelrute!\n\nKlickt zum Angeln einfach im Berufefenster auf das Angelsymbol. Achtet auf den Schwimmer, klickt darauf, wenn er zuckt, und schon habt Ihr Euren Fisch!", progress = "Fangt 5 Goldkarpfen. Versucht es ohne Angelrute!", completion = "Lasst mich mal sehen… Ja, die sind sehr schön. Gute Arbeit! Hier, nehmt ein paar mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[32686] = { id = 32686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloses Banner des Mantisreiches", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
