quests[32705] = { id = 32705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest Reward Summary: PvE Stage 5" }
quests[32706] = { id = 32706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in den Schatten", description = "Die Shado-Pan sind vor uns hier angekommen und sie arbeiten bereits daran, die Armeen des Donnerkönigs zu sabotieren.\n\nIch möchte, dass Ihr Euch mit Taran Zhu, dem Anführer der Shado-Pan, trefft und ihm Eure Dienste im Namen der Kirin Tor anbietet. Ich bezweifle, dass er wirklich Hilfe braucht, aber die Geste selbst ist wichtig genug.", sourceObjective = "Sprecht in der Tristen Höhle mit Taran Zhu.", completion = "Willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32707] = { id = 32707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse auf der Insel des Donners", description = "Da gibt es etwas, um das ich Euch bitten möchte, {class}.\n\nUns ist ein mächtiger Ritualstein in die Hände gefallen, den die Mogu der Shan'ze benutzen, um ihre Verbündeten in die Schlacht zu rufen, aber wir brauchen mehr als einen, um ihre Rituale auszuführen.\n\nWenn Ihr drei dieser Steine finden könnt, bringt sie mir. Wir können unsere Truppen sammeln und diese Steine benutzen, um einige von Lei Shens mächtigsten Dienern direkt in unsere Fallen zu locken.", sourceObjective = "Beschafft Euch 3 Ritualsteine der Shan'ze. Die Steine sind sehr selten, und es könnte eine Weile dauern, sie zu sammeln.", progress = "Habt Ihr die Steine gefunden, von denen ich sprach?", completion = "Perfekt. Ich werde Euch zeigen, wie man diese Steine benutzt, und dann könnt Ihr mit dem Überfall beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32708] = { id = 32708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Falle stellen", description = "Bringt diese 3 Ritualsteine an den Ort, den ich auf Eurer Karte markiert habe. Dort werdet Ihr ein Ritualobjekt der Shan'ze finden, mit dem Ihr einen ihrer mächtigen Verbündeten anlocken könnt.\n\nIhr werdet fähige Begleiter an Eurer Seite brauchen, damit diese Falle funktioniert. Geht nicht allein, es wird sich um einige der mächtigsten Diener des Donnerkönigs handeln.\n\nWenn sich Euer Feind zeigt, zeigt keine Gnade.", sourceObjective = "Benutzt 3 Ritualsteine der Shan'ze, um einen Champion des Donnerkönigs herbeizurufen, und tötet ihn.", progress = "Ist der Überfall gelungen?", completion = "Sehr beeindruckend.\n\nFalls Ihr noch mehr Steine findet, solltet Ihr mit dieser Strategie weitermachen. Es wird sicher eine Weile dauern, bis ihnen auffällt, was wir anstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32709] = { id = 32709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in den Schatten", description = "Die Shado-Pan sind vor uns hier angekommen und sie arbeiten bereits daran, die Armeen des Donnerkönigs zu sabotieren.\n\nIch möchte, dass Ihr Euch mit Taran Zhu, dem Anführer der Shado-Pan, trefft und ihm Eure Dienste im Namen der Sonnenhäscher anbietet. Ich bezweifle, dass er wirklich Hilfe braucht, aber die Geste selbst ist wichtig genug.", sourceObjective = "Sprecht in der Tristen Höhle mit Taran Zhu.", completion = "Willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32710] = { id = 32710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was riecht denn hier so?", description = "Euch fällt ein Gestank vor Euch auf, der stärker ist als gewöhnlich. Euer Magen dreht sich um, als der schwere Gestank Eure Nase erreicht.\n\nIhr erkennt diesen Geruch: Saurok. Verwesendes, weggeworfenes Saurokfleisch, getränkt von den widerlichen Abwässern des Abwasserkanals.", sourceObjective = "Findet und vernichtet Fleisch'rok den Verpesteten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32711] = { id = 32711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angst und Anima", description = "Ihr bemerkt, dass die Initialen E.K. kunstvoll und mit kalligraphischer Präzision in die Seite des Animus graviert worden sind.\n\nVor Euch steht Erzritualist Kelada, der Schöpfer des Animus. Auf Befehl des Donnerkönigs arbeitete Kelada ruhelos daran, die perfekte Methode zur Nutzung der großen Macht der Anima zu entwerfen. Etwas Praktisches, Beeindruckendes, Vernuftbegabtes und vor allem... etwas Tödliches.\n\nEr muss aufgehalten werden, bevor dieser nächste Entwurf vom Donnerkönig zum Leben erweckt wird.", sourceObjective = "Tötet Erzritualist Kelada.", sourceObjectiveStatus = "unverified-source-field" }
quests[32712] = { id = 32712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zao'cho der Hinterhältige", description = "Elektrizität summt in der Ferne, kitzelt Eure Ohren, und lässt Euch Schauder den Rücken herunterlaufen. Eure Finger werden taub und Euer Herz pocht, als Ihr Euch der Tür vor Euch nähert.\n\nZao'cho steht arrogant auf der Treppe vor Euch, webt Blitze zwischen seinen Finger und feixt Euch mit wahnwitziger Belustigung entgegen.", sourceObjective = "Tötet Zao'cho.", sourceObjectiveStatus = "unverified-source-field" }
quests[32713] = { id = 32713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ton, Steine, Sterben", description = "Es ist unmöglich, in Worten den gigantischen Schrecken aus Steinen, Knochen und Blut zu beschreiben, der gedanken- und ziellos vor Euch her marschiert.\n\nHeftige Erdbeben zerreißen die scheinbar hohle Erdkruste unter ihm und hinterlassen nur Zerstörung. Es scheint, als hätte er Eure Anwesenheit nicht bemerkt.", sourceObjective = "Tötet Krankenstein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32714] = { id = 32714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sturm besänftigen", description = "Ihr hört eine wilde, kriegerische Stimme aus der Ferne brüllen. Ein knisternder Sturm schwillt an und umwirbelt eine wolkenverhangene, schattenhafte Figur. Blitze zucken, und No'ku Sturmsprecher erscheint. Sein strafender Blick ist geradewegs auf Euch gerichtet.", sourceObjective = "Tötet No'ku Sturmsprecher.", sourceObjectiveStatus = "unverified-source-field" }
quests[32715] = { id = 32715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requiem für eine Königin", description = "Eine kalte Brise umhüllt Euren Körper und ein mulmiges Gefühl der Trauer überkommt Euch. Euer Herz wird schwer, als Ihr die schwachen, melodischen Rufe von Monara hört, der letzten Königin der Mogu.\n\nIhr liebliches Requiem hallt durch die Luft, beugt und formt sich in eine geisterhafte Hand, die nach Eurer Seele greift. Als sie sich darum schließt, seht Ihr eine kurze Vision von Monaras letzten Momenten... ihren brutalen Tod durch Lei Shens Hand.\n\nDas Lied wird zu reiner Trauer, und Monara weint und schluchzt lauter und lauter in die Dunkelheit.", sourceObjective = "Bettet Monara zur ewigen Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32716] = { id = 32716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Donnerkönigs", description = "Als der Nebel sich von den gefallenen Wächtern löst, fühlt Ihr eine plötzliche Erschütterung.\n\nDie Felsen, die die Abwasserkanäle blockieren, fallen nach vorn und stürzen in die Überlaufbehälter unter sich, und vier ekelerregende Augen springen aus der Dunkelheit.", sourceObjective = "Setzt Euch gegen den Überfall zur Wehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[32717] = { id = 32717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RECYCELT MICH" }
quests[32718] = { id = 32718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsrunen der Mogu", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einer Schicksalsrune der Mogu werden wertvolle Artefakte im Palast des Donnerkönigs sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 50 geringe Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32719] = { id = 32719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsrunen der Mogu", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einer Schicksalsrune der Mogu werden wertvolle Artefakte im Palast des Donnerkönigs sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 50 geringe Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32720] = { id = 32720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Eure Aufgabe", sourceObjective = "Tötet 10 Einheiten oder Spielercharaktere der Kirin Tor auf der Insel des Donners.", sourceObjectiveStatus = "unverified-source-field" }
quests[32721] = { id = 32721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Eure Aufgabe", sourceObjective = "Tötet 10 Einheiten oder Spielercharaktere der Kirin Tor auf der Insel des Donners.", sourceObjectiveStatus = "unverified-source-field" }
quests[32722] = { id = 32722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiede voraus!", description = "Ihr habt noch mehr zu tun. \n\nTötet Itoka, den Schmiedemeister, und findet ein Kodexfragment bei Fleischschmied Hoku, dem Torhüter des Donnerkönigs.", sourceObjective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment von Fleischschmied Hoku auf der Insel des Donners ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32723] = { id = 32723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "recycelt mich", description = "Ihr habt noch mehr zu tun. \n\nTötet Itoka, den Meister der Schmiede, und findet ein Kodexfragment bei Fleischschmied Hoku, dem Torhüter des Donnerkönigs.", sourceObjective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment vom Mogutorhüter auf der Insel des Donners ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32724] = { id = 32724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiede voraus!", description = "Ihr habt noch mehr zu tun. \n\nTötet Itoka, den Meister der Schmiede, und findet ein Kodexfragment bei Fleischschmied Hoku, dem Torhüter des Donnerkönigs.", sourceObjective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment vom Mogutorhüter auf der Insel des Donners ein.", progress = "Nun?", completion = "Gute Arbeit. Was Ihr heute getan habt, bringt uns einen Schritt näher an unser endgültiges Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32725] = { id = 32725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Warlock - Reached Kanrethad" }
quests[32726] = { id = 32726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt also Schmied werden…", description = "Es ist zwar am besten, die Eigenschaften der einfachen Metalle zu erlernen und Euch hochzuarbeiten, aber es ist möglich zu lernen, wie man ein guter Schmied wird, indem man die verschiedenen Anwendungen von Geistereisen für den alltäglichen Gebrauch erlernt. Wenn Ihr diesen Pfad wählen wollt, um ein Zenmeister der Schmiedekunst zu werden, kann ich Euch die ersten Schritte zeigen. Welchen Pfad Ihr auch wählt, Ihr könnt Euch meinen Respekt verdienen, indem Ihr mir beweist, dass Ihr einen geisterhaften Dietrich herstellen könnt.", sourceObjective = "Erschafft einen geisterhaften Dietrich, indem Ihr 500 Fertigkeitspunkte in Schmiedekunst erlangt. Falls Ihr Euch mithilfe von Pandarenmaterialien in der Schmiedekunst üben wollt, könnt Ihr von Jorunga Steinhuf ein Eurer Fertigkeitsstufe angemessenes Ausbildungsprojekt erhalten.", progress = "Wie machen sich Eure Studien?", completion = "Gut gemacht. Ihr seid bereit, ein Zenmeister der Schmiedekunst zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32727] = { id = 32727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contributed to Server Percentage Daily Tracking Quest" }
quests[32728] = { id = 32728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Knochen", description = "Die Mogu im nahegelegenen Hof der Knochen stellen eine konstante Bedrohung für unsere Präsenz auf dieser Insel dar. Großmagister Rommath wurde damit beauftragt, ihre Vorhaben zu unterbinden, aber <ein fähiger/eine fähige:c> {class} an seiner Seite wäre ihm dabei sicherlich von großer Hilfe.\n\nBegebt Euch zu ihm und geht ihm nach besten Kräften zur Hand.", sourceObjective = "Findet Großmagister Rommath außerhalb des Hofs der Knochen.", completion = "Ja, sehr gut. Kommt nur. Es gibt Arbeit zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32729] = { id = 32729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Za'Tual", description = "Die Zandalari haben seit unserer Ankunft stets eine lästige Bedrohung dargestellt. Ich habe Halduron Wolkenglanz damit beauftragt, ihre Position in Za'Tual im Süden zu schwächen.\n\nMeldet Euch bei ihm, sobald Ihr die Gelegenheit bekommt – er wird etwas für Euch zu tun haben.", sourceObjective = "Findet Halduron Wolkenglanz außerhalb von Za'Tual.", completion = "Noch jemand, der sich der Zandalarijagd anschließen möchte? Gut. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[32730] = { id = 32730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihgalukklamm", description = "Aethas hat an der Ihgalukklamm im Südosten das Kommando übernommen und arbeitet weiter an seinem Plan, die Saurok auf die Zandalari und die Mogu zu hetzen.\n\nGeht zu ihm und helft ihm, wo immer Ihr könnt!", sourceObjective = "Findet Erzmagier Aethas Sonnenhäscher an der Ihgalukklamm.", completion = "Ihr kommt genau zum richtigen Zeitpunkt. Eure Hilfe hier ist wirklich vonnöten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32731] = { id = 32731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Knochen", description = "Die Mogu im nahegelegenen Hof der Knochen stellen eine der größten Gefahren für uns auf dieser Insel dar. Narasi Schneedämmerung wurde damit beauftragt, ihre Vorhaben zu unterbinden, aber <ein fähiger/eine fähige:c> {class} an ihrer Seite wäre ihr dabei sicherlich von großer Hilfe.\n\nBegebt Euch zu ihr und geht ihr nach besten Kräften zur Hand.", sourceObjective = "Findet Narasi Schneedämmerung außerhalb des Hofs der Knochen.", completion = "Ja, sehr gut. Kommt nur. Es gibt Arbeit zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32732] = { id = 32732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihgalukklamm", description = "Erzmagierin Modera hat an der Ihgalukklamm im Südosten das Kommando übernommen und arbeitet weiter an ihrem Plan, die Saurok auf die Zandalari und die Mogu zu hetzen.\n\nGeht zu ihr und helft ihr, wo immer Ihr könnt!", sourceObjective = "Findet Erzmagierin Modera an der Ihgalukklamm.", completion = "Ihr kommt genau zum richtigen Zeitpunkt. Eure Hilfe hier ist wirklich vonnöten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32733] = { id = 32733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Za'Tual", description = "Die Zandalari haben seit unserer Ankunft stets eine lästige Bedrohung dargestellt. Ich habe Erzmagier Lan'dalock damit beauftragt, ihre Position in Za'Tual im Süden zu schwächen.\n\nMeldet Euch bei ihm, sobald Ihr die Gelegenheit bekommt – er wird etwas für Euch zu tun haben.", sourceObjective = "Findet Erzmagier Lan'dalock außerhalb von Za'Tual.", completion = "Noch jemand, der sich der Zandalarijagd anschließen möchte? Gut. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[32744] = { id = 32744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'rokh Dead" }
