quests[32758] = { id = 32758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leser der toten Sprache", description = "Kehrt in Eure Hauptstadt zurück und findet einen Hexenmeisterlehrer, der womöglich mehr über den Kodex weiß.", sourceObjective = "Bringt den Kodex zu einem Hexenmeisterlehrer in Eurer Hauptstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32783] = { id = 32783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ga'nars Rache", description = "Der Kopf meines Bruders ist dicker als seine Axt, und er ist störrisch wie ein Gronn.\n\nAls Ga'nar uns verließ, hat er ein paar der stärksten Krieger unseres Klans mitgenommen und ist mit ihnen in Richtung Norden zur Dolchrachenschlucht gezogen. Wenn sie noch da draußen sind, müsst Ihr sie finden. Ga'nar hört nicht auf mich.\n\nWenn es sein muss, dann helft ihm, seine Rache zu üben. Aber Ihr müsst ihn uns wiederbringen.", sourceObjective = "Sucht Ga'nar in der Nähe der Dolchrachenschlucht.", completion = "Mein Bruder hat sich also nicht getraut, selbst zu kommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[32791] = { id = 32791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Jagd beginnen!", description = "Ich habe keine Zeit für das Gewinsel meines Bruders. Wir jagen bis zur Vollendung unserer Rache oder bis zum Tod.\n\nDer Häuptling der Donnerfürsten hat meinen Vater erschlagen und mich zum Sterben zurückgelassen. Ich werde ihm also seine drei Söhne nehmen. Dieser Wicht in meiner Faust ist davon der erste.\n\nDieser Unrat hat die Anzahl und die Positionen der Donnerfürsten in der gegenüberliegenden Schlucht preisgegeben.\n\nBegleitet uns, wenn Ihr Euch traut, dann werdet Ihr bezeugen können, wie echte Krieger vom Frostwolfklan kämpfen. Wenn Ihr mir in die Quere kommt, ist das Euer Ende.", sourceObjective = "Konfrontiert Herold Grotan.", completion = "Die Donnerfürsten glauben, ihre große Anzahl bedeutet Sicherheit.\n\nWir werden ihnen zeigen, dass sie nichts vor einem Rudel Frostwölfe auf der Jagd schützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32792] = { id = 32792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrannte Erde!", description = "Die Donnerfürsten sind mir mittlerweile ein Dorn im Auge, den ich nicht länger tolerieren werde.\n\nGeht Richtung Osten und lasst niemanden am Leben! Verbrennt ihre Vorräte! Lasst ihnen nichts, an das sie sich klammern könnten.\n\nSammelt Euch in der Wilden Schlucht im Osten, wenn alles erledigt ist.", sourceObjective = "Tötet Kur'ak den Binder, verbrennt die Vorräte der Donnerfürsten und zerstört die Ballisten der Donnerfürsten.", completion = "Hrmmm. Der Geruch brennender Donnerfürsten. Das gefällt mir, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32794] = { id = 32794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Gronn", description = "Die Donnerfürsten nehmen Gronn gefangen, um die Eiserne Horde zu verstärken. Zeigt diesen Narren, warum das KEINE Haustiere sind.\n\nFolgt uns in Grullocs Grotte und zerschlagt die Ketten der gefangenen Gronn. Lassen wir die Bestien selbst Rache an den Donnerfürsten nehmen.\n\nTrefft Euch mit uns bei Grullocs Unterschlupf unterhalb der Grotte, wenn Ihr fertig seid.", sourceObjective = "Befreit 3 gefangene Gronn.", completion = "Viele Jahre habe ich an der Seite meines Vaters Jagd auf alle Arten von Beute gemacht. Diese Jagd soll sein Andenken ehren und seinen Tod durch die Hand dieser verräterischen, ehrlosen Donnerfürsten rächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32795] = { id = 32795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Älteste", description = "Dort ist Hatock, der älteste und letzte überlebende Sohn des Eisenwolfs. Er ist einer der besten Jäger, die die Donnerfürsten je ins Feld geschickt haben.\n\nEr war dabei, als sein Vater meinen Vater ermordet und mich meinem Schicksal überlassen hat.\n\nWenn ich mit ihm fertig bin, wird er es bereuen, die Sache damals nicht zu Ende gebracht zu haben.", sourceObjective = "Helft Ga'nar, seine Rache zu bekommen.", completion = "Heute ist ein guter Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[32796] = { id = 32796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Garnison", description = "Mein Vater ist gerächt. Die Söhne des Eisenwolfs sind alle erschlagen.\n\nGeht zur Garnison, die Eure Leute im Süden aufbauen. Kündigt dort meinem Bruder, diesem Zauderer, meine Rückkehr an.\n\nEs wird Zeit, dass der \"Häuptling\" daran erinnert wird, was es bedeutet, ein Frostwolf zu sein.", sourceObjective = "Trefft Euch mit Durotan in Eurer Garnison im Frostfeuergrat.", completion = "Ga'nar kommt. Gut. Wir brauchen seine Streitmacht, wenn wir unseren Vorteil ausnutzen wollen.\n\nIch kann nur hoffen, dass sein Kampfrausch genug abgeklungen ist, dass er für Vernunft zugänglich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[32803] = { id = 32803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Kiste der Donnerfürsten 01" }
quests[32804] = { id = 32804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besitztümer der Gefallenen", description = "Auch auf einer Vergeltungsmission müssen wir daran denken, die Ehre zu wahren, wie es sich für Frostwölfe gehört.\n\nIn der Grotte unten befinden sich die Leichname vieler ehrenhafter Frostwölfe. Wir müssen ihrer gedenken.\n\nSeht Euch nach Gegenständen unserer gefallenen Brüder um, während Ihr Ga'nars Auftrag ausführt. Bringt mir diese Gegenstände, damit ich sie einem Schamanen übergeben kann, der sie gemäß unseren Bräuchen zur letzten Ruhe betten wird.", sourceObjective = "Sichert 10 Artefakte eines gefallenen Frostwolfs.", progress = "Habt Ihr die Sachen gefunden?", completion = "Ihr habt unserem Klan Ehre erwiesen. Diese Tat soll nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32805] = { id = 32805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Erhabenen", description = "Ich würde Euch ja mit dem ganzen Spektrum meiner Drachenkräfte ausstatten, aber leider würde das Eure sterbliche Hülle zerreißen. Dennoch besteht Hoffnung – ich glaube, ich kann ein mächtiges Gefäß für Euch erschaffen.\n\nDazu benötige ich die Segen der vier Himmlischen Erhabenen in Pandaria. Reist mit mir zu den vier Tempeln und wir werden mit jedem von ihnen sprechen. Um Euch ihrer Gaben würdig zu erweisen, müsst Ihr eine ihrer Herausforderungen bestehen.\n\nEs wird nicht einfach werden. Wählt die Herausforderung aus, die Eurer Ausrüstung und Euren Fähigkeiten am ehesten entspricht!", sourceObjective = "Reist zum Tempel des Weißen Tigers am Kun-Lai, zum Tempel des Roten Kranichs in der Krasarangwildnis, zum Tempel der Jadeschlange im Jadewald und zum Niuzaotempel in der Tonlongsteppe, um die vier Segen der Erhabenen zu erhalten. Besteht EINE der vier möglichen Herausforderungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32806] = { id = 32806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König und der Rat", description = "Ich freue mich, dass Ihr gekommen seid, {name}. Ich habe mein Traumgebräu eingesetzt, um von Ereignissen in der ganzen Welt zu erfahren, aber je mehr ich erfahre, desto verwirrender erscheinen sie mir.\n\nSo hat etwa König Wrynn die Zwerge aus Eisenschmiede um mehr Truppen gebeten, doch sie unterstützen ihn nicht alle.\n\nIch werde Euch mehr berichten, aber erzählt mir zuerst von Euren eigenen Erfahrungen...", sourceObjective = "Schließt das Szenario Blutroter Schnee ab. Ihr könnt Euch dafür im Dungeonbrowser anmelden oder Lehrensucher Chos Traumgebräu verwenden.", progress = "Es ist nicht an mir, für die Entstehung dieser Geschichten zu sorgen – ich erzähle sie nur.", completion = "König Wrynn und die Dunkeleisenzwerge retteten also die Stadt und der tief zerstrittene Rat der Drei Hämmer fand unter dem Banner der Allianz zu neuer Einigkeit. Höchstinteressant!\n\nAber was geschieht mit der Horde?", sourceObjectiveStatus = "unverified-source-field" }
quests[32807] = { id = 32807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshäuptling und die Dunkelheit", description = "Ich kann jetzt erkennen, wie der König der Allianz sein Volk anführt. Aber was hat der Kriegshäuptling der Horde vor? Gleich unterhalb von uns lässt er einen Schwarm Goblins die Erde unseres geheiligten Tals umgraben. Was hofft er dort zu finden? Wir müssen es herausfinden!", sourceObjective = "Schließt das Szenario Das dunkle Herz Pandarias ab. Ihr könnt Euch dafür im Dungeonbrowser anmelden oder Lehrensucher Chos Traumgebräu verwenden.", progress = "Es ist nicht an mir, für die Entstehung dieser Geschichten zu sorgen – ich erzähle sie nur.", completion = "Waaaaas? Die Überreste eines Alten Gottes liegen unter Pandaria begraben? Kein Wunder, dass das Land so heimgesucht wird!\n\nDas Trachten des Kriegshäuptlings nach dieser schlummernden Macht entzweit die Horde, deren Anführer er ist. Seine Vision ist engstirnig, aber sehr, sehr gefährlich. Ich muss die Shado-Pan sofort davon in Kenntnis setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32808] = { id = 32808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen Feldarbeit", description = "Mein Traumgebräu kann mir nicht alles sagen. Seine Visionen sind verstreut in Raum und Zeit. Aber es ist klar zu erkennen, dass sich in Orgrimmar, der Hauptstadt der Horde, etwas Großes zusammenbraut.\n\nIhr solltet Euch dort hinbegeben und es mit eigenen Augen sehen!\n\nIn meinem Traumgebräu sehe ich zwei tapfere Spione der Allianz allein in Durotar. Ich sehe \"Amber\" und \"Sully\"...\n\nVielleicht erinnert Ihr Euch an sie? Ich glaube, sie brauchen Eure Hilfe!\n\nIhr findet Amber und Sully in Kalimdor, nahe der Knochenhöhle, an einem Ort, der als Blockade von Dranosh'ar bekannt ist.", sourceObjective = "Lasst Euch von Gliep Klatschknips am Schrein der Sieben Sterne nach Kalimdor bringen. Sprecht dann mit Amber Kearnen, die die Messerbucht nahe der Knochenhöhle in Durotar ausspäht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32809] = { id = 32809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen sammeln", description = "Garrosh baut seine Truppenstärke in Orgrimmar weiter aus – die Stadt gleicht einer Festung!\n\nKönig Wrynn wird keinen direkten Angriff riskieren, solange er nicht über mehr Informationen verfügt.\n\nBenutzt Projekt K4723, um durch die Blockade zu navigieren. Sammelt so viele Informationen wie möglich. Sucht nach allen Schriftstücken mit hoher Priorität und möglichen Schwachpunkten, die wir ausnutzen können. Haltet Eure Augen und Ohren offen und Euren Kopf unten!", sourceObjective = "Beschafft Informationen über die Versorgungslinien der Kor'kron, die Operation: Zerstörung der Dunkelspeere und die Kommandoposten der Kor'kron und befreit die Gefangene.", sourceObjectiveStatus = "unverified-source-field" }
quests[32810] = { id = 32810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rebellion der Dunkelspeere", description = "So, die Trolle rebellieren also ganz offen? Das können wir zu unserem Vorteil nutzen! Wenn sie eine zweite Front errichten, kann Garrosh die Stadt unmöglich gegen uns beide verteidigen.\n\nIch habe einen sehr riskanten Auftrag für Euch. Tretet als Repräsentant der Allianz auf und führt Gespräche mit Vol'jin vom Stamm der Dunkelspeere.\n\nVersucht, die gefangene Trollfrau zu finden, die wir aus den Fängen der Kor'kron befreit haben. Hieß sie nicht Zen'tabra?\n\nEs könnte unsere einzige Chance sein, Garrosh in die Knie zu zwingen...", sourceObjective = "Sprecht mit Zen'tabra oberhalb von Klingenhügel in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[32811] = { id = 32811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtfeld: Brachland", description = "Ihr wollt, dass wir zusammenarbeiten, aber zuerst müsst Ihr mein Vertrauen gewinnen.\n\nIm Nördlichen Brachland bereiten sich die Kor'kron auf einen Krieg vor. Die horten massenhaft Holz, Öl, Stein und Fleisch. Diese Vorräte wollen wir gegen sie verwenden.\n\nGeht ins Brachland, tötet die Kor'kron und bringt mir ihre Vorräte. Eskortiert Vorratskarawanen und schließt Euch mit anderen zusammen, um die Anführer auszuschalten. Tut, was nötig ist.\n\nBeweist mir, dass die Allianz es ernst meint! Ich werde Euch beobachten.", sourceObjective = "Sammelt 15 Stück Holz der Kor'kron, 15 Einheiten Öl der Kor'kron, 15 Portionen Fleisch der Kor'kron und 15 Steine der Kor'kron.", sourceObjectiveStatus = "unverified-source-field" }
quests[32812] = { id = 32812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkspear Rebellion" }
quests[32813] = { id = 32813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um Sen'jin", description = "<Kriegstrommeln erschallen in der Ferne.>\n\n{class}, Ihr seid immer zur rechten Zeit am rechten Ort. Höllschrei geht auf seine eigenen Leute los!\n\nEr wird erfahren, was es heißt, sich mit den Dunkelspeeren anzulegen. Kommt! Kämpft mit uns! Zeigen wir ihm, woraus die echte Horde gemacht ist!", sourceObjective = "Verteidigt Sen'jin gegen den Angriff der Kor'kron.", sourceObjectiveStatus = "unverified-source-field" }
quests[32814] = { id = 32814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um Klingenhügel", description = "Jetzt schlagen wir zurück! Wir werden Höllschrei keine Chance geben, seine Truppen neu zu formieren. Wir reiten nach Norden und töten jeden Kor'kron, den wir sehen.\n\nWenn wir Klingenhügel einnehmen, dann kontrollieren wir alle Straßen in Durotar.\n\nKommt! Reitet mit mir!", sourceObjective = "Befreit 6 Gefangene und besiegt die Anführer der Kor'kron, um Klingenhügel für die Dunkelspeerrebellen zu erobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[32815] = { id = 32815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Seher", description = "Ich kann Euch helfen, die verschiedenen Teile der Geschichte zu finden, aber Ihr müsst sie selbst zusammensetzen. Ich weiß vielleicht sogar, wo Ihr so etwas vollbringen könntet.\n\nIch habe von einem alten Gelehrten gehört, einem Seher namens Hao Pham Roo. Er ist so etwas wie ein... Experte für die Geschichte von Pandaria und könnte vielleicht den Ursprung des gegenwärtigen Chaos in Pandaria ans Licht bringen.\n\nSucht ihn auf, {name}. Das Letzte, was ich von ihm gehört habe, war, dass er vorhatte, den Fußstapfen des Kaisers zu folgen, indem er den Nimmerlaya in Kun-Lai erklimmt.", sourceObjective = "Findet Seher Hao Pham Roo an den Hängen des Nimmerlaya am Kun-Lai-Gipfel.", completion = "<Keucht> Oh, hallo... <Hustet> Hallo, mein junger Herr.\n\nGanz schön zugig hier oben, findet Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[32816] = { id = 32816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des letzten Kaisers", description = "Als den letzten Kaiser Zweifel plagten, beschritt er so lange einen einsamen Weg diesen Berg hinauf, bis er endlich seine Antworten gefunden hatte.\n\nIch bin hier, um denselben Weg zu gehen, und wie mir scheint, sucht auch Ihr nach Antworten auf Eure Fragen. Möchtet Ihr mich begleiten, auf dass wir beide unsere Antworten finden?\n\nAh, ich denke, ich werde alt, und dieser Schneesturm scheint meinen alten Knochen zu viel zuzumuten. Könnt Ihr vorausgehen und dieses Seil dort verankern? Ich kann mich dann allein daran entlangziehen.\n\nWir werden den Weg des letzten Kaisers gemeinsam beschreiten.", sourceObjective = "Befestigt ein Kletterseil an jeder Seilverankerung entlang des Weges, um Seher Hao Pham Roo dabei zu helfen, den Grat des Unwissenden zu erreichen.", completion = "Wir haben es geschafft, {class}! Vielen Dank. Hier, sucht Euch ruhig etwas aus diesem alten Krimskrams aus.\n\nAber leider muss ich gestehen, dass ich Euch gegenüber nicht ganz ehrlich gewesen bin...", sourceObjectiveStatus = "unverified-source-field" }
quests[32817] = { id = 32817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt das Szenario Blutroter Schnee ab" }
quests[32818] = { id = 32818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt das Szenario Das dunkle Herz Pandarias ab" }
quests[32819] = { id = 32819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield: Barrens" }
quests[32825] = { id = 32825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Use Me", sourceObjective = "Tötet 10 Einheiten oder Spielercharaktere der Kirin Tor auf der Insel des Donners.", sourceObjectiveStatus = "unverified-source-field" }
quests[32832] = { id = 32832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taran Zhu and Dezco Scene" }
quests[32836] = { id = 32836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine billige Brummelflüte", description = "Die \"Brummelflüte\" wurde unsorgfältig aus einer Baumwurzel geschnitzt und die Abstände zwischen den Löchern sind unregelmäßig.\n\nBei genauerem Hinschauen entdeckt Ihr auf der Unterseite eingeritzte Wörter:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die billige Brummelflüte zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Was habt Ihr da, {class}?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32837] = { id = 32837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opa Brummelflüte", description = "Die Herausforderungskarte, die ich heute für Euch habe, ist für einen Grummel mit dem niedlichen Namen Opa Brummelflüte. Die Grummel sind zwar nicht wirklich für ihr Geschick im Kampf bekannt, doch sie haben erstaunliches Glück.\n\nVielleicht liegt es ja an ihren Glücksbringern?", sourceObjective = "Besiegt Opa Brummelflüte, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Ihr habt toll gekämpft da draußen! Auch wenn er klein war.\n\nDas habt Ihr Euch wirklich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[32838] = { id = 32838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Fabel von Liebe und Edelmut", description = "Ein kleines Kinderbuch. Es ist gebunden und in ziemlich gutem Zustand.\n\nAuf dem hinteren Buchdeckel entdeckt Ihr neben dem Buchrücken in kursiver Handschrift folgende Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt \"Der Bär und die Jungfrau hehr\" zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Da sieh mal einer an. Was habt Ihr mir hier gebracht?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32839] = { id = 32839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bär und die Jungfrau hehr", description = "Die Herausforderungskarte, die Ihr freigeschaltet habt, gehört einem ganz ungewöhnlichen Paar. Ich bin nicht sicher, ob eine weitere Beschreibung ihnen gerecht würde.\n\nVielleicht solltet Ihr einfach die Herausforderungskarte erwerben und Euch selbst überzeugen.", sourceObjective = "Besiegt den Bären und die Jungfrau, indem Ihr ihre Herausforderungskarte erwerbt und sie in der Kampfgilde herausfordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[32840] = { id = 32840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don-Dons Lunte", description = "Inmitten der Fleisch- und Fellstückchen von Ho-zen, die wild um Kota Kons zerstörerische Sphäre wirbeln, scheint Ihr eine kurze Lunte erwischt zu haben.\n\nSie besteht ausschließlich aus verwobenen und verfilzten Ho-zen-Haaren und riecht stark.\n\nAm einen Ende der Zündschnur entdeckt Ihr ein kleines Papieretikett mit folgender Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt Don-Dons Lunte zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Was für ein Geruch kommt mir da entgegen?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32841] = { id = 32841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister Don-Don", description = "Ihr habt eine Karte für einen bombenwerfenden Ho-zen namens Meister Don-Don freigeschaltet.\n\nDie zerstörerische Kraft von Sprengkörpern zieht die Ho-zen zwar von Natur aus an, doch sie lernen selten den richtigen Umgang damit, bevor sie sich selbst in die Luft sprengen. Meister Don-Don ist die Ausnahme.\n\nViel Glück!", sourceObjective = "Besiegt Meister Don-Don, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Ich bin nicht sicher, was ich denken soll. Ich wollte ja, dass Ihr gewinnt, aber... irgendwie wollte ich Euch auch explodieren sehen.\n\nNichts für ungut! Ich mag Explosionen einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[32842] = { id = 32842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne wie Messer", description = "Der Zahn spitzt sich zu einer scharfen Kante zu, fast wie wenn er geschärft worden wäre. Er gehörte offensichtlich einer wilden Bestie.\n\nWährend Ihr ihn behutsam in der Hand haltet, fällt Euch eine gekonnt eingravierte Inschrift auf:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den ausgesprochen scharfen Zahn zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Ihr habt etwas für mich – das sehe ich in Euren Augen. Was ist es, {class}?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32843] = { id = 32843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grinsezahn", description = "Die Herausforderungskarte, die Ihr heute freigeschaltet habt, ist für eine der tödlichsten Kreaturen der Südlichen Meere: Grinsezahn. Ein einziger Biss seiner scharfen Zähne und von Euch ist nur noch ein unkenntlicher Haufen Haut, Blut und Gedärme übrig.\n\nViel Spaß!", sourceObjective = "Besiegt Grinsezahn, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Herzlichen Glückwunsch!\n\nSowieso, wie peinlich wäre es denn gewesen, wenn ein gestrandeter Hai Euch gefressen hätte?", sourceObjectiveStatus = "unverified-source-field" }
quests[32844] = { id = 32844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnis des Schleims", description = "Der Inhalt der Phiole wirbelt und schäumt wild, was sie in Eurer Hand zittern lässt. Als Ihr hineinschaut, glaubt Ihr, kurz einen Blick auf ein wütendes lebendes Gesicht zu erhaschen.\n\nDer Pfropfen der Flasche passt genau. An seinem Rand entdeckt Ihr eine geschickt eingeschnitzte Inschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die Phiole mit rötlichem Schleim zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Seid gegrüßt, {class}.", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32845] = { id = 32845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splat", description = "Vielleicht kennt Ihr Blat schon, einen unserer Herausforderer zweiten Ranges hier bei der Kampfgilde. Die Herausforderungskarte, die Ihr verdient habt, ist für Splat, seine fiesere ältere Schwester.\n\nVersucht, Euch nicht umbringen zu lassen, {name}. Und wenn Ihr doch draufgeht, dann macht es für uns wenigstens unterhaltsam!", sourceObjective = "Besiegt Splat, indem Ihr ihre Herausforderungskarte erwerbt und sie in der Kampfgilde herausfordert.", completion = "Ihr habt eine ziemliche Sauerei hinterlassen, doch Ihr habt es geschafft. Gut gemacht, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[32846] = { id = 32846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modifizierter Mampfapparat", description = "Ihr hättet diesen modifizierten Mampfapparat vielleicht gar nicht als solchen erkannt, wenn jemand nicht groß \"MODIFIZIERTER MAMPFAPPARAT\" darauf gekritzelt hätte.\n\nGleich unter der schludrig gemalten Aufschrift seht Ihr eine kleinere, in leuchtend roter Tinte und viel schöner geschrieben:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den modifizierten Mampfapparat zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Kann ich Euch helfen?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32847] = { id = 32847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mecha-Bruce", description = "Jeder kennt Bruce. Jeder liebt Bruce! Und irgendwann tötet jeder Bruce.\n\nEin Orcjäger mit einem Händchen für Technik fand das schade, darum hat er sich einen Krokilisken besorgt und ihn etwas aufgerüstet.\n\nMit der Herausforderungskarte, die Ihr verdient habt, dürft Ihr gegen Mecha-Bruce kämpfen. Das wird bestimmt ein Blutbad. Die Frage ist nur... schnappt Ihr zu, oder werdet Ihr zugeschnappt?", sourceObjective = "Besiegt Mecha-Bruce, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Och... armer Mecha-Bruce.\n\nIch gebe Euch Eure Belohnung. Aber das heißt nicht, dass ich es gerne tue.", sourceObjectiveStatus = "unverified-source-field" }
quests[32848] = { id = 32848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostige Eierschale", description = "Ein Stück einer Eierschale, wahrscheinlich von einem Pinguin. Die Ränder sind mit Raureif bedeckt und die Krümmung zeigt, dass das intakte Ei ziemlich groß gewesen sein muss.\n\nKomischerweise steht im Inneren der Eierschale mit jadegrüner Tinte eine Nachricht geschrieben:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die frostige Eierschale zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Ihr seht aus wie ein Bote. Was habt Ihr für mich, {race}?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32849] = { id = 32849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planschi und Platschi", description = "Veteranen der Kampfgilde erinnern sich bestimmt an den Pinguin Planschi. Planschi ist nicht der begabteste Herausforderer der Kampfgilde, doch leicht umschubsen kann man ihn auch nicht!\n\nEigentlich, wenn ich es recht bedenke, lässt er sich schon eher leicht umschubsen...\n\nEgal! Mit der Karte, die Ihr verdient habt, könnt Ihr ihn und seinen größeren älteren Bruder Platschi herausfordern. Die beiden mögen sich vielleicht leicht umschubsen lassen, doch das wird nicht verhindern, dass einer oder beide Euch irgendwann totschlagen.", sourceObjective = "Besiegt Planschi und Platschi, indem Ihr ihre Herausforderungskarte erwerbt und sie in der Kampfgilde herausfordert.", completion = "Ich hätte nie geglaubt, dass ich das sage, aber es ist das erfolgreiche Vermöbeln von ein paar Pinguinen, das den echten und bewährten Grubenkämpfer verrät. Ihr habt Eure Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[32850] = { id = 32850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modell vom letzten Jahr", description = "Dieser Roboter ist in einem schlechten Zustand. Er hat mehrere eingebaute Sockel, die wahrscheinlich wie beim Blingtron 4000 einst Edelsteine enthielten, jetzt aber leer sind.\n\nAuf der sonst staubbedeckten Hinterseite des Roboters seht Ihr ein glänzendes kleines Metallschild mit folgender geprägter Inschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den staubigen alten Roboter zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Was habt Ihr da, {class}?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32851] = { id = 32851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 3000", description = "Erst mit der Markteinführung des Modells 4000 hat die Blingtronreihe richtig Erfolg gehabt. Nur wenige erinnern sich an den Blingtron 3000, doch er war schon für sich ein echtes Wunderwerk der Ingenieurskunst!\n\nMit der Herausforderungskarte, die Ihr freigeschaltet habt, könnt Ihr es hier in der Kampfgilde mit Blingtron 3000 aufnehmen.\n\nGlückspilz!", sourceObjective = "Besiegt den Blingtron 3000, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", progress = "Um den Blingtron 3000 herauszufordern, müsst Ihr seine Herausforderungskarte erwerben.\n\nZu Eurem Glück habe ich hier zufällig eine...", completion = "Ihr habt ein Händchen fürs Verdreschen von Robotern, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32852] = { id = 32852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erdschneider des Grabungsmeisters", description = "Dem Aussehen nach ein ganz gewöhnlicher Spaten. Am Griff ist in Kursivschrift \"Der Erdschneider des Grabungsmeisters\" eingeschnitzt.\n\nAuf der anderen Seite des Griffs entdeckt Ihr jedoch ein kleineres Etikett in einfacher Schrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den Erdschneider des Grabungsmeisters zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Was habt Ihr da, {class}? Etwas für mich?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32853] = { id = 32853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mingus Diggs", description = "Ihr habt Euch das Recht verdient, den Archäologen Mingus Diggs herauszufordern!\n\nMingus ist nicht so ein zäher Brocken, habe ich jedenfalls gehört... doch die Verantwortlichen erlauben ihm, einige seiner ausgegrabenen Schätze in den Kampfring mitzunehmen. Auf die werdet Ihr aufpassen wollen.\n\nKommt und erwerbt seine Karte, wenn Ihr bereit seid!", sourceObjective = "Besiegt Mingus Diggs, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Ihr seid so schnell in der Arena herumgerannt, mir hat einen Moment lang der Kopf gedreht.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[32854] = { id = 32854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgetragene Augenbinde", description = "Ein Stück Stoff, das um einen menschlichen Kopf passen würde. Der Stoff ist schlicht und schmucklos, abgesehen von einem kleinen Etikett am einen Ende mit folgender Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die abgetragene Augenbinde zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Ihr habt etwas für mich, stimmt's?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32855] = { id = 32855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der blinde Held", description = "Mit der Herausforderungskarte, die Ihr freigeschaltet habt, dürft Ihr den blinden Helden herausfordern, einen mysteriösen Krieger aus längst vergangenen Zeiten. Niemand übertrifft sein Können mit einer Klinge. Niemand.\n\nNa ja, zum Glück kann er nichts sehen. Viel Spaß!", sourceObjective = "Besiegt den blinden Helden, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Normalerweise sollte man sich schämen, gegen einen Blinden zu kämpfen, doch in diesem Fall muss ich Euch mein Lob aussprechen.\n\nGroßartig gekämpft, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[32856] = { id = 32856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Papier umwickelter Stein", description = "Eine seltsame Kombination. Das Papier umschließt den Stein vollständig, der im Vergleich dazu kaum größer als ein Kiesel ist.\n\nWenn Ihr das Papier gegen das Licht haltet, seht Ihr ein deutliches Wasserzeichen mit folgendem Text:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den mit Papier umwickelten Stein zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Guten Tag, {race}. Habt Ihr etwas für mich?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32857] = { id = 32857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ro-Shambo", description = "Mit der Herausforderungskarte, die Ihr freigeschaltet habt, dürft Ihr Ro-Shambo herausfordern, eine esoterische Kreatur aus unbekannten Gefilden.\n\nPasst auf. Wie ich höre, hat er einige Tricks auf Lager.", sourceObjective = "Besiegt Ro-Shambo, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Ihr habt gut gekämpft! Auch wenn Euch das Glück etwas unter die Schultern gegriffen hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[32858] = { id = 32858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorbalgboxhandschuhe", description = "Die Handschuhe sind mit groben Stichen genäht und wurden nach dem Geruch zu urteilen mit Kriechersekret behandelt. Sie erscheinen dennoch strapazierfähig und funktionstüchtig.\n\nIhr seid nicht sehr erstaunt, als Ihr im Innensaum folgende Aufschrift entdeckt:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die Raptorbalgboxhandschuhe zu einem Mitglied der Kampfgilde Eurer Fraktion.", progress = "Was habt Ihr da, {class}?", completion = "Ah, Ihr habt einen meiner Schätze gefunden. Gute Arbeit, Abenteurer.\n\nIm Gegenzug dürft Ihr eine meiner seltenen Herausforderungskarten erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32859] = { id = 32859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ty'thar", description = "Ihr habt Euch das Recht verdient, eine Herausforderungskarte zu erwerben, und zwar für einen Troll namens Ty'thar.\n\nTy'thar hat einen sehr individuellen Kampfstil und als Teil seiner Abmachung mit der Kampfgilde müsst Ihr seine Regeln befolgen:\n\n - Mann-zu-Mann-Faustkampf. Kein Herumrennen.\n\n - Der dritte Niederschlag entscheidet den Kampf.\n\nViel Glück!", sourceObjective = "Besiegt Ty'thar, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", completion = "Ich bin beeindruckt! Ihr seid in die Arena hinein und habt Ty'thar mit seinen eigenen Waffen geschlagen.\n\nBitteschön. Das habt Ihr Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[32860] = { id = 32860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Razor Hill Tracking Quest" }
quests[32861] = { id = 32861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umhang der Tugend", description = "Wir haben, was wir brauchen. Ich kann einen Gegenstand anfertigen, der die Kräfte der Erhabenen beherbergen kann und, mit etwas Anstrengung, vielleicht auch einige von meinen eigenen.\n\nTrefft mich oberhalb von des Steinmetz' Torheit, östlich der Taverne im Nebel auf der Verhüllten Treppe, wo wir uns schon diverse Male getroffen haben. Ihr werdet von dem Ergebnis begeistert sein!", sourceObjective = "Begebt Euch nach des Steinmetz' Torheit auf der Verhüllten Treppe und sprecht mit Furorion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32862] = { id = 32862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield: Barrens" }
quests[32863] = { id = 32863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wofür wir trainiert haben", description = "Seid Ihr bereit, Eure Haustiere einer Prüfung zu unterziehen? Die Kampfhaustierarena ist kein Platz für niedrigstufige Angsthasen. Besser, Ihr habt einen Raketenbot dabei und seid auf alles gefasst. Wenn Ihr über drei vollständig ausgebildete Haustiere verfügt, dann sucht Kämpfe gegen Trainer mit ähnlichen Fähigkeiten und zeigt der Welt, was Ihr drauf habt. Die Anweisungen dazu findet Ihr in Eurem Haustierführer.", sourceObjective = "Besiegt 10 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", completion = "Ich hörte Geschichten über einige Eurer Kämpfe. Offensichtlich waren sie vielen ein unvergessliches Erlebnis! Ich glaube, dass Ihr Euch diese Belohnung verdient habt. Glückwunsch, Trainer, und leistet weiterhin so gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32864] = { id = 32864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence - Riko Tracking" }
quests[32865] = { id = 32865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence - Nazgrim Tracking" }
quests[32866] = { id = 32866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intelligence - Zaela Tracking" }
quests[32867] = { id = 32867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jin von den Dunkelspeeren", description = "Willkomm'n in Sen'jin. Ich weiß, Ihr kommt von weit her, um Vol'jin zu seh'n, den Anführer der Dunkelspeere.\n\nAber ich muss Euch bitt'n, Euch noch 'nen Moment zu geduld'n. Zuerst sollt'n wir uns unterhalt'n.", sourceObjective = "Hört Ki'ta Pfeilzahn zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[32868] = { id = 32868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen, Buch II", description = "Die Geschichten von Glückspilz Yi, Grauhuf und Huscher Xi'a werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", sourceObjective = "Besiegt Glückspilz Yi, Grauhuf und Huscher Xi'a.", completion = "Ich verneige mich vor Euch, der weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32869] = { id = 32869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen, Buch III", description = "Die Geschichten von No-No, Ti'un dem Wanderer und Blutstachel werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", sourceObjective = "Besiegt No-No, Ti'un den Wanderer und Blutstachel.", completion = "Ich verneige mich vor Euch, der weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32870] = { id = 32870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffsvorbereitung", description = "Die Dinge sind in Bewegung, {name}. Bevor wir die finale Phase meines Plans ausführen, müssen wir noch eine letzte Aufgabe erfüllen.\n\nMeine Agenten berichten mir, dass König Wrynn nach seinen Verlusten in Theramore eine neue Seeflotte aufgestellt hat und dass Vol'jin in offener Rebellion gegen den Kriegshäuptling gen Norden durch Durotar marschiert.\n\nSprecht erneut mit mir, sobald beide sich den Toren nähern. Wir werden diesem Krieg zu einem glorreichen Ausgang verhelfen!", sourceObjective = "Kehrt zu Furorion in der Taverne im Nebel an der Verhüllten Treppe zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[32871] = { id = 32871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jin von den Dunkelspeeren", description = "Ich werd' Euch zu Vol'jin bring'n.", sourceObjective = "Begleitet Zen'tabra zu Vol'jin.", sourceObjectiveStatus = "unverified-source-field" }
quests[32872] = { id = 32872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtfeld: Brachland", description = "Unsre Arbeit is' noch lang nich' getan, {name}. Falls Ihr nochma' für die Dunkelspeere Euren Kopf hinhaltet, dann werd ich dafür sorg'n, dass Ihr reich belohnt werdet.", sourceObjective = "[Wöchentliche Quest] Sammelt 150 Stück Holz der Kor'kron, 150 Einheiten Öl der Kor'kron, 150 Portionen Fleisch der Kor'kron und 150 Steine der Kor'kron.", sourceObjectiveStatus = "unverified-source-field" }
