quests[32892] = { id = 32892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg zieht auf", description = "Als Ihr das Tal betretet, bemerkt Ihr einen rundlichen Pandaren, der Euch vom Balkon oberhalb des Mogu'shanpalastes aus stürmisch zuwinkt. Es sieht so aus, als wenn Lehrensucher Cho Eure Aufmerksamkeit erregen wollte. Ihr solltet herausfinden, was los ist!", sourceObjective = "Sprecht mit Lehrensucher Cho.", sourceObjectiveStatus = "unverified-source-field" }
