quests[32895] = { id = 32895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebellion!", description = "Ihr da! Ich habe gerade eine Meldung von unseren Agenten in Durotar erhalten.\n\nDie Rebellion der Dunkelspeere benötigt Eure Hilfe.\n\nIhr habt ja bereits einige Erfahrungen mit den Trollen gemacht. Warum begebt Ihr Euch nicht nach Durotar und findet heraus, was dort vor sich geht?", sourceObjective = "Sprecht mit Ki'ta Pfeilzahn nordwestlich von Klingenhügel in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[32896] = { id = 32896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to War" }
