quests[32899] = { id = 32899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tägliches zufälliges Szenario (Ntes) (Mists)" }
quests[32900] = { id = 32900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldentaten", description = "Ich halte diese Langeweile nicht mehr aus – nie komme ich hier raus!\n\nIhr seht aus, als hättet Ihr schon einige Abenteuer erlebt. Wenn Ihr mir eine wirklich heroische Geschichte bringt, dann habe ich für Euch etwas Besonderes, das Euch sicher interessieren wird.", sourceObjective = "Schließt ein Szenario auf dem Schwierigkeitsgrad 'Heroisch' ab.", completion = "Herzlichen Glückwunsch, {name}, Ihr habt es geschafft! Bevor ich es vergesse: Hier ist die besondere Belohnung, die ich Euch versprochen hatte – ich hoffe, sie gefällt Euch.\n\nNun erzählt mir alles über Euer Abenteuer. Habt Ihr dem sicheren Tod ins Auge geschaut? Freunde gefunden? Ich wünschte mir, ich hätte mehr Freunde wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32901] = { id = 32901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldentaten", description = "Ich halte diese Langeweile nicht mehr aus – nie komme ich hier raus!\n\nIhr seht aus, als hättet Ihr schon einige Abenteuer erlebt. Wenn Ihr mir eine wirklich heroische Geschichte bringt, dann habe ich für Euch etwas Besonderes, das Euch sicher interessieren wird.", sourceObjective = "Schließt ein Szenario auf dem Schwierigkeitsgrad 'Heroisch' ab.", completion = "Herzlichen Glückwunsch, {name}, Ihr habt es geschafft! Bevor ich es vergesse: Hier ist die besondere Belohnung, die ich Euch versprochen hatte – ich hoffe, sie gefällt Euch.\n\nNun erzählt mir alles über Euer Abenteuer. Habt Ihr dem sicheren Tod ins Auge geschaut? Freunde gefunden? Ich wünschte mir, ich hätte mehr Freunde wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32910] = { id = 32910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "recycelt mich", description = "Ihr habt noch mehr zu tun. \n\nTötet Itoka, den Meister der Schmiede, und findet ein Kodexfragment bei Fleischschmied Hoku, dem Torhüter des Donnerkönigs.", sourceObjective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment vom Mogutorhüter auf der Insel des Donners ein.", sourceObjectiveStatus = "unverified-source-field" }
