quests[32924] = { id = 32924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[32929] = { id = 32929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel hilft immer viel", description = "Donnerfürsten verbringen ihre Tage damit, die Jagd in der Gruppe zu üben, aber einzeln sind sie schwach. Ihre Stärke liegt in der Überzahl.\n\nWenn wir gewinnen wollen, müssen wir also dafür sorgen, dass sie weniger werden.\n\nWährend wir durch die Dolchrachenschlucht vorrücken, tötet alle Donnerfürsten, die sich Euch in den Weg stellen. Das wird ihren Klan schwächen.", sourceObjective = "Tötet 15 Donnerfürsten in der Dolchrachenschlucht im Frostfeuergrat.", completion = "Eine beachtliche Anzahl, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[32935] = { id = 32935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[32941] = { id = 32941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Oaseneismutter" }
quests[32942] = { id = 32942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Sonnenhäscheransturm I", description = "<Yoon hat sich bei dieser Bestellung kurz gehalten und dennoch nichts Wichtiges weggelassen.>\n\nEine weitere Bestellung der Horde hat uns erreicht. Der Sonnenhäscheransturm von der Insel des Donners hat einen Scheffel Frühlingszwiebeln angefordert.\n\nAuch wenn sich mir beim Konflikt zwischen der Horde und der Allianz immer noch das Fell sträubt, werde ich keine hungrigen Mäuler ungestopft lassen.", sourceObjective = "Pflanzt 8 Frühlingszwiebelsamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[32943] = { id = 32943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Sonnenhäscheransturm II", description = "Sobald Eure Frühlingszwiebeln erntereif sind, müsst Ihr sie nur noch für die Abholung einpacken.\n\nDenkt Euch nur, Eure Frühlingszwiebeln werden ein Teil des Kampfes Eurer Fraktion in Pandaria sein!", sourceObjective = "Erntet 8 reife Frühlingszwiebelpflanzen und liefert 40 Frühlingszwiebeln an den Sonnenhäscheransturm.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Werft die Frühlingszwiebeln in die Kiste! In Kürze wird ein Vertreter des Sonnenhäscheransturms eintreffen, um sie mitzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32944] = { id = 32944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Offensive der Kirin Tor I", description = "<Yoon hat sich bei dieser Bestellung kurz gehalten und dennoch nichts Wichtiges weggelassen.>\n\nEine weitere Bestellung der Allianz hat uns erreicht. Die Offensive der Kirin Tor von der Insel des Donners hat einen Scheffel saftigleckerer Karotten angefordert.\n\nAuch wenn sich mir beim Konflikt zwischen der Horde und der Allianz immer noch das Fell sträubt, werde ich keine hungrigen Mäuler ungestopft lassen.", sourceObjective = "Pflanzt 8 saftigleckere Karottensamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[32945] = { id = 32945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Offensive der Kirin Tor II", description = "Sobald Eure saftigleckeren Karotten erntereif sind, müsst Ihr sie nur noch für die Abholung einpacken.\n\nDenkt Euch nur, Eure saftigleckeren Karotten werden eine Menge Soldaten an der Front ernähren!", sourceObjective = "Erntet 8 reife saftigleckere Karottenpflanzen und liefert 40 saftigleckere Karotten an die Offensive der Kirin Tor.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Werft die saftigleckeren Karotten in die Kiste! Ein Vertreter der Kirin Tor wird in Kürze eintreffen, um sie abzuholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32946] = { id = 32946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diesmal wird alles anders" }
