quests[32952] = { id = 32952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST", description = "Ich brauche Hilfe! Meine Schafe wurden von Drachen gestohlen! Könnt Ihr 10 von ihnen töten?", sourceObjective = "Tötet Drachen.", sourceObjectiveStatus = "unverified-source-field" }
