quests[32973] = { id = 32973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avatar of Flame Kill Tracking Quest" }
quests[32974] = { id = 32974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolos Rätsel", description = "<Das Lederpergament ist sehr alt. Neben den Flecken, die das Alter hinterlassen hat, ist Folgendes zu lesen:>\n\nAuf der Insel der Zeit vier Männer steh'n\nRund und stark sind sie zu seh'n\nVon diesen Brüdern der Kürzeste zeigt\nWo der Pfad zu mir abzweigt.", sourceObjective = "Löst das Rätsel.", completion = "<Die Erde sieht aus, als ob sie aufgewühlt wurde. Vielleicht liegt dort etwas vergraben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32975] = { id = 32975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolos Rätsel", description = "<In der Erde liegt noch ein dreckiger Pergamentfetzen begraben.>\n\nWo die Hoffnung steht, Flügel gespreizt\nAm besten du nach Norden eilst\nSchreite durch ein uraltes Tor\nHinter einem Steinpaar tret ich hervor.", sourceObjective = "Löst das Rätsel.", completion = "<Noch ein Erdhaufen! Könnte hier etwas vergraben liegen?>", sourceObjectiveStatus = "unverified-source-field" }
quests[32976] = { id = 32976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolos Rätsel", description = "Mein Schatz ruft, der letzte Schritt\nÜber des Wassers hohen Ritt\nIm Schatten oben in der Höh'\nBleibt kein Pfad, nur Hauch und Bö.", sourceObjective = "Löst das Rätsel.", completion = "<Die uralte Truhe liegt hier schon lange ungestört.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32979] = { id = 32979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Scharfseherfelsen", sourceObjective = "Sucht Draka und Drek'Thar am Scharfseherfelsen im Frostfeuergrat.", completion = "Ihr schon wieder? Habt Euch also noch nicht von Ogern fressen oder von Donnerfürsten töten lassen? Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[32980] = { id = 32980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elementfresser", description = "Drek'Thar hat bereits mit seinem Ritual begonnen. Es ist mächtig genug, um die Aufmerksamkeit der hiesigen Goren zu wecken. Diese Tiere werden von Elementarmagie angezogen wie Fliegen von einem Kadaver.\n\nIch werde schon bald alle Hände voll zu tun haben. Helft uns, wenn Ihr wollt, aber Drek'Thar muss sein Ritual beenden können.", sourceObjective = "Verteidigt Drek'Thar, solange er sein Ritual durchführt.", completion = "Ich bin hergekommen, um die Elemente um Hilfe zu bitten. Jetzt sehe ich, dass wir es sind, die ihnen helfen müssen.\n\nKommt, {name}, seht, was ich gesehen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32981] = { id = 32981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur dem Sieger", description = "Ich bin Gronnjäger Rokash und ich diene nur den Siegern.\n\nIch habe von Euren Taten gehört, Kommandant, und die Leichen gesehen, die Ihr und Eure Truppen hinterlassen haben.\n\nIch bin meines Klans überdrüssig. Es sind Weichlinge, Schwächlinge und Verlierer.\n\nIch fordere Euch heraus: Geht zum Gigantensturz im Norden und tötet Himmelssängerin Strag. Holt Euch ihr Totem als Trophäe, und Ihr sollt mein neuer Häuptling sein.", sourceObjective = "Besorgt Himmelssängerin Strags Totem.", progress = "Strag war schon immer ein Feigling. Sie versteckte sich hinter ihrer Magie und ihrer Stellung als Medium für die Toten.", completion = "Strag war die Marionette des Eisenwolfs. Sie handelte nur auf seinen Befehl.\n\nDas schwächte uns, und von einer Macht, die man fürchten musste, wurden wir zum leichten Ziel.\n\nWenn das aus den Donnerfürsten geworden ist, dann will ich nichts mit ihnen zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32983] = { id = 32983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schatten der Riesen", description = "Die Goren und der Magnaron überfallen die Elementargeister und schmelzen ihre Essenz wie Stahl in der Esse.\n\nKommandant, nehmt mein Totem und reist nach Osten nach Magnarok. Bitte sucht und befreit die Geister.\n\nDraka und ich werden uns zum Frostfeueraufstieg durchschlagen. Wir sehen uns dort, wenn Ihr Erfolg habt.", sourceObjective = "Rettet Flammrog und Zundeck.", completion = "Das habt Ihr gut gemacht, {class}.\n\nWir brauchen die Hilfe dieser Kinder, wenn die Zeit gekommen ist, Exurotus zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32984] = { id = 32984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg", description = "Ich kann die Stimme des Zorns am oberen Ende des Aufstiegs förmlich spüren. Kommt, lasst uns diese Treppe gemeinsam überwinden.\n\nSeid wachsam. Die Goren dieser Gegend werden vom Geruch eines Schamanen vermutlich angezogen.\n\nWenn wir getrennt werden, zieht Euch zum Fuß der Treppe zurück und wartet auf die anderen.", sourceObjective = "Bringt Drek'Thar zu Exurotus, dem Geist des Frostfeuers.", completion = "Dies ist uralte Magie aus einer Zeit vor den Orcs. Es wird nicht leicht sein, sie zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32985] = { id = 32985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Frostfeuers", description = "Sobald ich mit dem Ritual zur Befreiung von Exurotus beginne, wird es sicherlich Kron zu uns locken.\n\nNormalerweise braucht man eine Armee von erfahrenen Kriegern, um einen Magnaron zu besiegen. Aber es gibt nur uns drei.\n\nAchtet auf meine Feuertotems auf dem Schlachtfeld. Ich werde versuchen, so viel Macht von Exurotus zu beziehen wie möglich. Tretet in die Nähe der Totems und werdet eins mit dem Zorn.\n\nTötet Kron mit dieser Macht! Lok'tar ogar!", sourceObjective = "Besiegt Kron.", completion = "Nach Krons Niederlage kann ich jetzt die Magie bewältigen, die Exurotus in ihrem Bann hält. Aber es könnte bereits zu spät sein. So viel des Zorns ist schon vom Magnaron und den Goren verbraucht und entzogen worden.\n\nIch fürchte, dass wir diesem Geist lediglich einen friedlichen Tod erkauft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32989] = { id = 32989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Südens", description = "Im Südosten gibt es einen Außenposten, der von den Streitkräften der Donnerfürsten bedrängt wurde, als sie durch die Schluchten nach Wor'gol marschiert sind.\n\nIch habe Verstärkung losgeschickt, um den Außenposten zu sichern und Richtung Osten nach Grom'gar vorzurücken. Wir werden die Donnerfürsten gänzlich aus unserem Land vertreiben und sie bis zu dem stinkenden Leichnam zurückjagen, den sie ihr Zuhause nennen.\n\nDrakas Schwester Lokra war unter den Orcs, die sich freiwillig gemeldet haben, den Steinzahnposten zu säubern.", sourceObjective = "Sprecht mit Lokra am Steinzahnposten.", completion = "{name}! Man sagte mir, dass Ihr auf dem Weg hierher seid. Ihr seid spät dran! Wir sind gerade beim Aufräumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32990] = { id = 32990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Standhaften", description = "Die Belagerung wurde gebrochen... Sie haben die Widerstandsfähigkeit des Steinzahns unterschätzt und die Verstärkungseinheiten der Speerspießer haben sie ziemlich überrascht.\n\nSobald wir hier mit dem Aufräumen fertig sind, werden wir alle versammeln, die noch kämpfen können, und uns auf den Marsch gen Grom'gar vorbereiten.\n\nDer Hauptmann des Außenpostens, Karg Blutfuror, hätte mittlerweile herauskommen sollen, um sich mit uns zu treffen. Könnt Ihr ihn herausbringen?\n\nSagt ihm, dass Lokra wartet. Er weiß, wie ungern ich warte.", sourceObjective = "Sprecht mit Karg Blutfuror im Steinzahnposten.", completion = "Ihr seid zurück! Aber wo ist Karg?", sourceObjectiveStatus = "unverified-source-field" }
quests[32991] = { id = 32991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Knochenschlucht", description = "Die Donnerfürsten haben in der Knochenschlucht Gefangene gemacht?\n\nWorauf warten wir noch?! Wir müssen sofort hinterher!\n\nIhr sucht nach den vermissten Dorfbewohnern, Asha und ich werden Karg aufspüren.", sourceObjective = "Durchsucht die Knochenschlucht nach den vermissten Frostwolforcs.", completion = "Danke, dass Ihr nach den anderen gesucht habt. Karg und seine Entführer sind uns einen Schritt voraus, aber weit kommen sie nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32992] = { id = 32992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegliches Ziel", description = "Kargs Entführer bewegen sich in Richtung Osten. Wahrscheinlich ziehen sie sich mit eingezogenen Schwänzen nach Grom'gar zurück.\n\nSie glauben vielleicht, mir entkommen zu können. Aber Asha ist das schnellste Wesen auf vier Beinen. Wir werden sie einholen und in den Eishauchwehen stellen.", sourceObjective = "Schließt zu Lokra in den Eishauchwehen auf.", completion = "<Lokras Blick bleibt starr auf ihren sterbenden Frostwolf gerichtet.>\n\nWir hatten sie... Wir hatten sie, Asha. Du warst so schnell. So schön.\n\nIch habe dich im Stich gelassen, Asha. Es tut mir so leid.", sourceObjectiveStatus = "unverified-source-field" }
quests[32993] = { id = 32993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke unserer Bande", description = "Asha ist von uns gegangen, doch teilen wir ein Band, das der Tod nicht durchtrennen kann. Sogar jetzt noch drängt mich ihr Geist weiter nach Grom'gar.\n\nDer Eisenwolf behauptet, dass Beziehungen uns schwächen... dass Liebe uns verwundbar macht.\n\nEr irrt sich.\n\nKarg ist meine Stärke, und ich bin seine. Ich werde ihn von seinen Ketten befreien, und zusammen werden wir den Donnerfürsten zeigen, wie stark unsere Bindung sein kann.", sourceObjective = "Findet Karg Blutfuror in Grom'gar.", completion = "Nehmt mir diese Ketten ab. Wir haben etwas zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32994] = { id = 32994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flankenfeuer", description = "Wenn wir jetzt aufbrechen, wird der Großangriff meines Klans auf Grom'gar in einer Katastrophe enden.\n\nUnsere Krieger sind zwar im Nahkampf nicht zu schlagen, doch verfügen die Donnerfürsten über neue Distanzwaffen. Unsere Streitmacht würde aufgerieben, während sie die Eishauchwehen überquert.\n\nAber WIR sind bereits hier. Wir können diese Waffen übernehmen, bevor sie auch nur einen Schuss abgeben.\n\nDie Orcs des Schwarzfelsklans helfen unseren Feinden, diese \"Kanonen\" in den Werkstätten an der Südseite zu schmieden. Wenn wir ihre eigenen Werkzeuge verwenden, um die Waffen zu sabotieren, hinterlassen wir Grom'gar komplett ungeschützt gegen einen Angriff der Frostwölfe.", sourceObjective = "Verwendet Schwarzfelssprengpulver, um 5 Kanonen der Eisernen Horde in Grom'gar zu zerstören.", progress = "Wenn diese Kanonen funktionstüchtig bleiben, werden meine Brüder und Schwestern sterben. Was muss ich noch mehr sagen?", completion = "Seht nur, wie ihre Maschinen sie im Stich lassen! Es gibt keine besseren Waffen als die Muskeln von Orcs!", sourceObjectiveStatus = "unverified-source-field" }
quests[32997] = { id = 32997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Zesqua" }
quests[33008] = { id = 33008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Tal", description = "Ah, ich habe auf Eure Ankunft gewartet, <Reisender/Reisende>.\n\nIch wünschte, wir könnten uns unter besseren Umständen treffen, aber leider ist die derzeitige Situation im Tal alles andere als erfreulich.\n\nAber lasst uns im Moment nicht darüber sprechen. Besucht Madame Vee Luo im Schrein der Zwei Monde.\n\nSie wird Euch dabei helfen, Euch einzuleben.", sourceObjective = "Sprecht mit Madame Vee Luo im Schrein der Zwei Monde im Tal der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33010] = { id = 33010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eisenwolf", description = "Mein Bruder Ga'nar ist an meiner Seite.\n\nWor'gol, der Steinzahnposten und Eure Garnison halten stand.\n\nUnser Klan ist vereint und die Donnerfürsten wurden in die Flucht geschlagen. Wir sind bereit. Die Zeit ist reif, diesem \"Eisenwolf\" gegenüberzutreten.", sourceObjective = "Betretet die Jägerhalle in Grom'gar und besiegt den Eisenwolf.", completion = "Danke, dass Ihr meine Familie beschützt habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33011] = { id = 33011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Andenken eines Frostwolfveterans" }
quests[33013] = { id = 33013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer und Donner", description = "Der Eisenwolf... hat Waffen mitgebracht...\n\n<hust>\n\n...Waffen mit Feuer und Donner.\n\nNoch nie haben unsere Krieger solche Waffen gesehen. Darauf waren wir nicht vorbereitet.\n\n<keuch> Wir müssen lernen... sie zu bezwingen...", sourceObjective = "Untersucht die Belagerungsmunition und die schwere Panzerung in der Knochenschlucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[33014] = { id = 33014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Glutrachen" }
quests[33016] = { id = 33016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Vorratslager der Frostwölfe" }
quests[33017] = { id = 33017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Vorratskarren der Eisernen Horde" }
quests[33018] = { id = 33018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lang vergessene Nudelgeheimnisse", description = "Beim Durchsuchen des Gerölls findet Ihr ein Bruchstück eines alten Schilds. Nachdem Ihr den Staub weggewischt habt, könnt Ihr sehr verwitterte, pandarische Zeichen erkennen: \"Nudeln\" und \"Lin\".\n\nAls Ihr aufseht, kommt Euch der Verdacht, dass dieses Schild zu einem Gasthaus auf der Brücke gehört hat, die nun in Trümmern vor Euch liegt. Ein Lokal auf einer Brücke klingt nach einer eher provisorischen Einrichtung, der Eigentümer könnte daher gut in der Nähe wohnen.\n\nVielleicht findet sich ein Hinweis in dem Dorf hier auf der Insel?", sourceObjective = "Durchsucht das Dorf Alt-Pi'jiu auf der Zeitlosen Insel nach dem Eigentümer des Bruchstücks des alten Schilds.", completion = "Ah, hallo. Ich bin Lin Chao-Wei.\n\nSeid Ihr hergekommen, um die berühmte Nudelsuppe meiner Familie zu kosten?", sourceObjectiveStatus = "unverified-source-field" }
quests[33019] = { id = 33019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NC S1 Q2", description = "Hallo! Ich bin Lin Chao-Wei. Seid Ihr gekommen, um die berühmte Nudelsuppe meiner Familie zu kosten? Leider muss ich Euch enttäuschen. Mein Vater ist gestorben, bevor er mir die geheime Zutat für seine Geheimzutatnudelsuppe verraten konnte. Er hat jedoch erwähnt, dass er das Rezept für einen Freund aufgeschrieben hat, der zum Tempel der Jadeschlange gegangen ist. Vielleicht könnt Ihr es dort finden?" }
quests[33020] = { id = 33020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verlorene Geheimnis der Geheimzutat", description = "Wenn Ihr hergekommen seid, um die berühmte Nudelsuppe meiner Familie zu probieren, habt Ihr leider kein Glück.\n\nMein Vater ist verschieden, bevor er mir die Geheimzutat verraten konnte. Er hat allerdings erwähnt, er hätte das Rezept für einen seiner Freunde niedergeschrieben, der im Tempel der Jadeschlange studiert hat.\n\nVielleicht könnt Ihr dort danach suchen?", sourceObjective = "Besiegt das Sha des Zweifels.", completion = "Ihr seht den Namen Lin auf der Schriftrolle. Ein paar Zeilen tiefer erkennt Ihr das Zeichen für \"Rezept\".\n\nDas muss sie sein!\n\nEure einzige Sorge ist, dass die Sha-Energien aus den Geschichten der Pandaren auch die Schriftrolle verderbt haben könnten.\n\nEs gibt nur einen Weg, es herauszufinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[33021] = { id = 33021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ewig verlorene Geheimnisse?", description = "<Mit dem alten Nudelsuppenrezept der Familie Lin in den Händen entscheidet Ihr Euch, zum Halbhügelmarkt aufzubrechen.>\n\n<Wenn irgendjemand in Pandaria diese Schriftrolle entziffern kann, dann ist das Sungshin Eisentatz.>", sourceObjective = "Sprecht mit Sungshin Eisentatz auf dem Halbhügelmarkt im Tal der Vier Winde.", completion = "Hallo, {name}. Was habt Ihr da?", sourceObjectiveStatus = "unverified-source-field" }
quests[33022] = { id = 33022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und tragen", description = "Meine Güte! Großvater hat mir immer Geschichten über den berühmten Nudelladen der Familie erzählt.\n\nTraurigerweise ist die Schriftrolle in einem schlechten Zustand, aber ich glaube, zusammen können wir das Rätsel lösen!\n\nZuerst benötigen wir eine Menge Getreide für die Nudeln.\n\nBegebt Euch zur Kornkammer und holt mit diesem Beutel etwas Getreide. Bringt den Beutel dann zu dem Wagen, den ich an der Kornkammer abgestellt habe.", sourceObjective = "Fangt mit dem Getreidefangbeutel 20 Getreidesäcke auf, die bei der Kaiserlichen Kornkammer von den Kornkammervandalen heruntergeworfen werden.\n\nWenn Ihr ein Reittier besteigt oder verletzt werdet, verliert Ihr alles Getreide, das Ihr bei Euch tragt.", completion = "Ausgezeichnete Arbeit, {name}! Ich glaube, mit diesem ganzen Getreide sind wir bereit anzufangen.\n\nIhr solltet vielleicht erst einmal versuchen, eine normale Nudelsuppe zu kochen. Probiert es mit diesem Rezept, das ich für Euch aufgeschrieben habe. Das wäre eine ausgezeichnete Übung.", sourceObjectiveStatus = "unverified-source-field" }
quests[33023] = { id = 33023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NC S1 Q6" }
quests[33024] = { id = 33024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist eine echte Maßeinheit?", description = "Gut gemacht, {name}. Wie ich sehe, seid Ihr bereit, die Mysterien um Lins Suppe mit Geheimzutat weiter zu erkunden.\n\nSoweit ich es bestimmen kann, hat Lin für seine Suppenbrühe Sturmbräu verwendet.\n\nIch glaube, Eure nächsten Schritte sollten darin bestehen, selbst einen Nudelwagen zu bauen und Euch zur Brauerei Sturmbräu zu begeben, um ein paar Schluck von dem Gebräu zu besorgen.", sourceObjective = "Baut einen Nudelwagen und sammelt 20 Schluck Gebräu von erschlagenen Bierlementaren in der Brauerei Sturmbräu.", progress = "Ich bin froh, dass es Eure Aufgabe ist und nicht meine. Ich bin eigentlich gar kein so großer Trinker.", completion = "Gut gemacht, {name}. Damit können wir eine wahrhaft einzigartige Suppenbrühe herstellen.\n\nIch konnte ein paar aktuellere Baupläne für einen Nudelwagen bekommen. Mit dieser Brühe werdet Ihr Euren Betrieb sicherlich weiter ausbauen wollen.\n\nDanach müsst Ihr die Geheimzutat von Lins Nudelsuppe mit Geheimzutat suchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[33025] = { id = 33025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NC S2 Q2" }
quests[33026] = { id = 33026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind nicht Eure fettigen Ziegensteaks", description = "Ich bin so aufgeregt, {name}. Wir haben fast alle Zutaten für die Nudelsuppe bekommen!\n\nWir haben hier jede Menge Gemüse und Gewürze, doch hatte die Familie Lin Zugang zu exotischem Fleisch, das seit einiger Zeit nicht mehr in Pandaria erhältlich ist. Wir brauchen etwas gutes, fettiges Fleisch.\n\nGroßvater hat mir immer von uralten Schildkröten erzählt, die an den Küsten der Zeitlosen Insel leben. Etwas, das so lange lebt, muss ziemlich gutes, fettiges Fleisch auf den Knochen haben.\n\nBaut einen Nudelwagen Deluxe und sammelt ein paar fettige Schildkrötensteaks, dann machen wir weiter.", sourceObjective = "Baut einen Nudelwagenbausatz Deluxe und sammelt 50 fettige Schildkrötensteaks.", progress = "Ich kann die Suppe schon fast schmecken!", completion = "Oh, die sind wunderbar, {name}.\n\nUnd nun zum letzten Schritt: die Geheimzutat von Lins Suppe mit Geheimzutat.\n\nJetzt habe ich fast einen Knoten in der Zunge!", sourceObjectiveStatus = "unverified-source-field" }
quests[33027] = { id = 33027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimzutat ist...", description = "Der beste Weg, dieses Vorhaben anzugehen, führt über praktische Erfahrung.\n\nIch habe Händler, Gelehrte und Bauern aus ganz Pandaria eingeladen, um Eure Suppen zu kosten. Wir werden die besten Ergebnisse erzielen, wenn Ihr ihnen die Suppen zuordnen könnt, die sie bevorzugen.\n\nNun ist es an der Zeit, die Geheimzutat zu suchen!", sourceObjective = "Reiht Euch für das Szenario Die Geheimzutat ein und schließt es ab.", progress = "{name}, wir müssen die Geheimzutat finden, wenn wir die Nudelsuppe der Familie Lin jemals meistern wollen!", completion = "Gut gemacht, {name}. Diese ganzen Leute sind hergekommen, um Eure Nudelsuppe zu probieren, und IHR habt sie sehr glücklich gemacht!\n\nVersteht Ihr das nicht? Die Geheimzutat liegt in Euch!\n\nJetzt zieht hinaus und bringt mit diesem brandneuen Nudelwagen Glück in die Welt!", sourceObjectiveStatus = "unverified-source-field" }
